    /// <summary>
    /// MPJ_10886 Accounting source explorer 
    /// </summary>
    private void metupadteFiscalCalendarYear()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp ;
        GeneralJournalEntry             metgeneralJournalEntry;
        FiscalCalendarYear              metfiscalCalendaryear;
        

        update_recordset metaccountingSourceExplorerTmp
            setting METFiscalYearName = metfiscalCalendaryear.Name
            join JournalNumber,FiscalCalendarYear from metgeneralJournalEntry
                where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
            join RecId,Name from metfiscalCalendaryear
                where metfiscalCalendaryear.RecId == metgeneralJournalEntry.FiscalCalendarYear;
    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer
    /// </summary>
    private void metupdatedueDateForCustTrans()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp;
        CustTrans                       metcustTrans;

        update_recordSet metaccountingSourceExplorerTmp
            setting METClosed = metcustTrans.Closed,
                    METDueDate = metcustTrans.DueDate,
                    METLastSettleVoucher = metcustTrans.LastSettleVoucher
            join Voucher, TransDate, Invoice, DocumentDate,Closed,DueDate,LastSettleVoucher from metcustTrans
                where metcustTrans.Voucher == accountingSourceExplorerTmp.SubledgerVoucher
                   && metcustTrans.TransDate == accountingSourceExplorerTmp.AccountingDate
                   && metcustTrans.Invoice != '';
    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer
    /// </summary>
    private void metupdatedueDateForVendTrans()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp;
        VendTrans                       metvendTrans;

        update_recordSet metaccountingSourceExplorerTmp
            setting METClosed = metvendTrans.Closed,
                    METDueDate = metvendTrans.DueDate,
                    METLastSettleVoucher = metvendTrans.LastSettleVoucher
            join Voucher, TransDate, Invoice, DocumentDate,Closed,DueDate,LastSettleVoucher from metvendTrans
                where metvendTrans.Voucher == metaccountingSourceExplorerTmp.SubledgerVoucher
                   && metvendTrans.TransDate == metaccountingSourceExplorerTmp.AccountingDate
                   && metvendTrans.Invoice != '';
    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer
    /// </summary>
    private void metmodifiedBy()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp;
        GeneralJournalEntry                 metgeneralJournalEntry;
        SubledgerVoucherGeneralJournalEntry metsubledgerVoucherGeneralJournalEntry;
        SubledgerJournalEntry               metsubledgerJournalEntry;
        AccountingEvent                     metaccountingEvent;
        TransactionLog                      mettransactionLog;

        update_recordset metaccountingSourceExplorerTmp
            setting METModifiedBy = mettransactionLog.CreatedBy
                join JournalNumber from metgeneralJournalEntry
             where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
                join GeneralJournalEntry from metsubledgerVoucherGeneralJournalEntry
            where metsubledgerVoucherGeneralJournalEntry.GeneralJournalEntry == metgeneralJournalEntry.RecId
                join Voucher,VoucherDataAreaId,TransferId,CreatedTransactionId from metsubledgerJournalEntry
            where metsubledgerJournalEntry.Voucher == metsubledgerVoucherGeneralJournalEntry.Voucher &&
                  metsubledgerJournalEntry.VoucherDataAreaId == metsubledgerVoucherGeneralJournalEntry.VoucherDataAreaId &&
                  metsubledgerJournalEntry.TransferId == metgeneralJournalEntry.TransferId
                join AccountingDate,RecId from metaccountingEvent
            where metaccountingEvent.AccountingDate == metsubledgerVoucherGeneralJournalEntry.AccountingDate &&
                  metaccountingEvent.RecId == metsubledgerJournalEntry.AccountingEvent
                join CreatedBy from mettransactionLog
            where mettransactionLog.CreatedTransactionId == metsubledgerJournalEntry.CreatedTransactionId;
            

    }
